import Foundation

private typealias E = EvidenceSeed

/// Alternate tellings, batch M: the same cases, played out another way.
extension StoryVariants {
    static let variantsM: [CaseTemplate] = [scaldChildAbuseV1, privateImagesPostV1, clubAmbushKillingV1, constructionDumpingV1, payrollClerkTheftV1, prankNineOneOneV1, revokedFamilyCrashV1, painClinicV1, homeInvasionV1, formerRoommateKeyV1, formerEmployeeFilesV1, heatOfPassionV1, postedPondV1, loyaltyCardClonesV1, jailLockdownRiotV1, lakeCrashFatalV1, pillPressV1, clerkShootsBackV1, toddlerFentanylV1, swattingCallV1, scaffoldNoHarnessV1, outboardMotorsV1, odometerRollbackV1, ballgamePistolV1, schoolZoneCrashV1, ediblesAtFestivalV1, payrollRobberyV1, nursingHomeNeglectV1, fakeAccountsV1, paradeSUVV1, lawnMowerNeighborV1, bingoHallV1, dogInHotCarV1]

    static let scaldChildAbuseV1 = SmallCases.make(
        key: "story.scaldChildAbuse",
        category: .family,
        headlines: ["Preschooler's Hands Burned at Home, Daycare Teacher Raises Alarm", "Glove-Pattern Burns Contradict Pot Story"],
        law: "felonyChildAbuse",
        threshold: 8,
        spec: "Intentionally inflicted serious bodily injury upon {V}, a child under sixteen, on {DATE}.",
        ages: 19...45,
        victim: true,
        summary: "A daycare teacher saw blistered skin up both of {V}'s forearms at drop-off on {DATE}. {D}, the caregiver, said {V} dragged a pot of boiling water off the stove the evening before. A burn clinic found a glove pattern on both hands with a clean line at each wrist. {DL} says it was a sudden accident.",
        state: [E(.forensic, 3, "Burn Clinic Report", "Glove-pattern burns on both hands with a clean line at each wrist."), E(.document, 3, "Daycare Incident Report", "Blisters noted at drop-off; no care sought the night before."), E(.physical, 2, "Stove Photos", "Pot handles turned inward, away from the edge.", .search)],
        defense: [E(.statement, 1, "Pot Pulled Down", "{DL} says {V} dragged the pot down by a handle.")],
        role: "Daycare teacher",
        exam: [.direct("What did you see at drop-off that morning?", "\"Blisters up both of {V}'s forearms, red and raised, and {V} flinched when I touched the sleeves. I knew right away something was wrong.\""), .direct("What did you do first?", "\"I took {V} to the sink room and ran cool water over the skin. Then I photographed the burns and filled out our incident report.\""), .direct("What did {D} tell you?", "\"That {V} dragged a pot of boiling water off the stove the evening before. {D} said it was a sudden accident and no doctor had seen {V} yet.\""), .direct("How did {D} seem at drop-off?", "\"Upset and quiet. {D} brought {V} on time, and I noticed {D} did not want to talk about it much.\""), .direct("What does your incident report say about care that night?", "\"It notes blisters at drop-off and that no medical care was sought the night before. {V} had been home with those burns for hours.\""), .direct("What did you do after writing the report?", "\"I called my director, and we sent {V} to a burn clinic. The clinic's report later described the pattern of the burns.\""), .cross("Were you at the home that evening?", "\"No. I was not there. I only know what I saw at drop-off and what {D} told me.\""), .cross("Has {D} ever hurt a child at your center?", "\"No. {D} has dropped off and picked up {V} for a long time, and we never saw injuries before.\""), .cross("Did {V} say how it happened?", "\"{V} is very young and said very little. {V} cried and held {V.his} arms close, and did not describe the stove.\""), .cross("Did {D} refuse to let you call the clinic?", "\"No. {D} agreed when we said we needed to send {V} for care, and came along.\""), .cross("How did {V} behave around {D} at drop-off?", "\"Clingy, but that is normal for {V}'s age. I did not see fear specific to {D}.\"")],
        defenseRole: "Pediatric nurse",
        defenseExam: [.direct("What is your role?", "\"I am a pediatric nurse. I have treated burns in children for many years, mostly scalds from kitchens and bathtubs.\""), .direct("Can a pulled pot burn both hands?", "\"Sometimes, if a child grabs on and the liquid runs down the arms. Burns on both limbs can happen that way.\""), .direct("What is a glove pattern burn?", "\"A burn that covers a hand evenly up to a clean line at the wrist, as if a glove was worn. It often suggests immersion.\""), .direct("Is a clean line at the wrist common in spills?", "\"That is unusual. Spills usually make splash patterns, with uneven edges and drip marks rather than an even band.\""), .direct("Does that mean it could not be an accident?", "\"No. I cannot say it could not happen. A child who grips the pot could have an even line, though it is rare.\""), .direct("What would you want to know to judge it?", "\"How the pot fell, how high the child was, and how quickly the water cooled. Those details change the pattern.\""), .cross("Did you treat {V}?", "\"I reviewed the clinic report. I did not treat {V} personally, so I am speaking from the report and the photographs.\""), .cross("Can you say {V}'s hands were held in water?", "\"I cannot say that. The pattern raises a question, but a question is not a conclusion.\""), .cross("Would a delay in seeking care be a concern?", "\"Yes. A burn like this needs prompt care. A long delay is something I note, but it is common when caregivers panic.\""), .cross("Did you see the stove?", "\"No. I only saw the photographs. The pot handles in those photos turned inward, away from the edge.\""), .cross("Is it common for burns to look worse the next day?", "\"Yes. Blisters form over hours, and burns look worse the next morning than at the moment of injury.\"")],
        theory: ("{D} held a child's hands in scalding water.", "A child pulled a pot down."),
        allocution: "\"I should have taken {V} in that night. I'm sorry.\"",
        truths: ("A voicemail that evening has {DL} saying {V} 'needs to learn the stove is hot.'", "A smart speaker log records {DL} asking for burn first aid seconds after a loud crash."),
        defendant: [.direct("What happened in the kitchen?", "\"I was at the sink. I heard a crash behind me, turned around, and {V} was on the floor with water everywhere.\""), .direct("What was on the stove?", "\"A pot of water for pasta. I had turned the handle in so it would not be bumped, and I thought it was safe.\""), .direct("What did you do right away?", "\"I picked {V} up and ran cold water over {V.his} hands and arms. {V} was screaming, and I was shaking.\""), .direct("Did you hold {V}'s hands in hot water?", "\"No. Never. I would never hurt {V}. I held {V} close and kept the cold water running.\""), .direct("Why did you not take {V} to a doctor that night?", "\"I ran cold water and thought it would settle. I was wrong. I should have gone straight to the emergency room.\""), .direct("What did you do the next morning?", "\"I took {V} to daycare as usual, because I did not realize how bad the blisters would look until then.\""), .cross("The clinic says the burns have a clean line at each wrist, doesn't it?", "\"That is what they say. I cannot explain it, and I did not do anything to cause it.\""), .cross("You waited hours without medical care, didn't you?", "\"Yes. I made a bad decision, and I will regret it forever. I thought it was a minor burn.\""), .cross("You told the teacher it was a sudden accident, didn't you?", "\"Yes, because it was. I told the teacher exactly what happened.\""), .cross("A pot with the handle turned in does not fall off a stove easily, does it?", "\"I do not know how {V} reached it. {V} climbed on a stool, and I did not see it happen.\""), .cross("You never called a doctor or the clinic yourself, did you?", "\"No. I did not. The daycare sent us to the clinic, and I went along.\"")],
        openings: ("A daycare teacher saw blistered skin up both of {V}'s forearms at drop-off. {D}, the caregiver, said {V} pulled a boiling pot off the stove, but a burn clinic found glove-pattern burns on both hands with a clean line at each wrist, and no care was sought the night before.", "{D} was at the sink when a pot fell, and {V} was burned in a sudden accident. {D} panicked, ran cold water, waited too long for a doctor, and has never hurt a child."),
        closings: ("Glove-pattern burns with a clean line at each wrist, a night without medical care, and a story of a falling pot. Burns shaped like that rarely come from a spill.", "A pot on a stove, a young child, and a caregiver who panicked. Delay was a mistake, not a crime, and the State has not shown {D} held anyone's hands in water."),
        timeline: [(-1, "6 p.m.: dinner is cooking."), (-1, "6:30 p.m.: {V}'s hands are burned."), (0, "7:45 a.m.: the teacher sees the burns."), (0, "10 a.m.: the burn clinic examines {V}.")],
        identified: "A daycare teacher.",
        aggravating: ["The victim was a young child"],
        mood: .wantsConviction,
        impact: "My child cannot hold a crayon.")

    static let privateImagesPostV1 = SmallCases.make(
        key: "story.privateImagesPost",
        category: .cyber,
        headlines: ["Cloud Album Link Sent to Parents and Coworkers After Breakup", "Ex Says Shared Account Was Open to Others"],
        law: "privateImages",
        threshold: 4,
        spec: "Knowingly disclosed private intimate images of {V} without consent, with intent to cause harm, on {DATE}.",
        ages: 23...35,
        victim: true,
        summary: "Five weeks after {V} ended a relationship with {D}, an anonymous email on {DATE} sent a cloud album link to {V}'s parents and two coworkers. The album held private photos {V} had shared only with {DL}. It sat in a cloud account in {DL}'s name. {DL} says the account was a shared plan, {V}'s old tablet was still signed in, and {D.he} did not send it.",
        state: [E(.digital, 3, "Cloud Access Log", "The album was created and shared at 11:20 p.m. from {DL}'s laptop on {DL}'s home connection.", .search), E(.digital, 3, "Email Header", "The anonymous message used a throwaway address whose recovery number is {DL}'s old line.", .search), E(.digital, 2, "Text After the Breakup", "{DL} to {V}: \"Your parents deserve to know who you really are.\"")],
        defense: [E(.document, 2, "Shared Plan", "Four devices were signed in to the account, including {V}'s old tablet."), E(.document, 1, "Unknown Device", "A fifth device logged in that week from another city.")],
        role: "Digital examiner",
        exam: [.direct("What did the cloud access log show?", "\"The album was created and shared at 11:20 p.m. from {D}'s laptop, on {D}'s home internet connection.\""), .direct("What did the anonymous email look like?", "\"It came from a throwaway address with no name. The recovery number tied to that address is {D}'s old phone line.\""), .direct("Who received the link?", "\"{V}'s parents and two coworkers, all at once, in one anonymous email on the same night.\""), .direct("What did the album contain?", "\"Private photos that {V} had shared only with {D}. The album sat in a cloud account that was in {D}'s name.\""), .direct("What was in the text {V} received after the breakup?", "\"From {D}: 'Your parents deserve to know who you really are.' It was sent about five weeks earlier.\""), .direct("How did you confirm the laptop was involved?", "\"By matching the device identifier in the access log to {D}'s laptop and the home connection that night.\""), .cross("How many devices were signed in to the account?", "\"Four, including {V}'s old tablet. The account was set up as a shared plan during the relationship.\""), .cross("Was there a fifth device?", "\"Yes. A device from another city had logged in earlier that week. I could not identify the owner.\""), .cross("Can you say who was typing at the laptop?", "\"No. The log shows the laptop and the connection, not the person. I cannot see through the screen.\""), .cross("Could someone with the laptop passcode have used it?", "\"Yes. Anyone who knew the passcode and was in the house could have.\""), .cross("Did you recover the deleted messages?", "\"Some. I will say the recovery showed the account was active during those hours, and little more.\"")],
        defenseRole: "Former roommate",
        defenseExam: [.direct("How do you know {D}?", "\"We lived together in the same house for about a year. We shared a kitchen and common areas.\""), .direct("Did anyone use the shared tablet?", "\"Everyone did, for movies. It stayed logged in to the shared plan, and no one bothered to sign out.\""), .direct("Who knew the laptop passcode?", "\"Everybody in the house. It was a simple code, and we all used each other's computers from time to time.\""), .direct("Was there a houseguest around that time?", "\"Several. People stayed over regularly, and visitors used the common room and the laptop sometimes.\""), .direct("How did {D} react to the breakup?", "\"Hurt and angry, like most people. {D} said some harsh things, but {D} also said {D.he} would move on.\""), .direct("Were you home on the night of the email?", "\"No. I was out that night, and I got home late.\""), .cross("So you cannot say who used the laptop that night?", "\"No. I was not there, and I cannot tell you who touched it.\""), .cross("Did you hear {D} say anything about {V}'s parents?", "\"Once, in anger. I took it as venting, not a plan, but I did hear it.\""), .cross("Did you ever see {D} with the photos?", "\"No. I never saw them. I only knew about the relationship in general terms.\""), .cross("Did {D} keep the cloud account active after the breakup?", "\"I believe so. It was a shared plan, and {D} paid for it.\""), .cross("Are you friendly with {D}?", "\"We were roommates and got along. I am telling you what I know and nothing more.\"")],
        theory: ("{D} shared {V}'s private photos to hurt {V.him}.", "A shared account that anyone in the house could use."),
        allocution: "\"I said ugly things. I did not send that link.\"",
        truths: ("{DL}'s browser history shows the album settings page opened a minute before the email.", "{DL}'s timeclock shows {D.him} at work until 11:50 p.m.; a houseguest was alone with the laptop."),
        defendant: [.direct("Did you send the link?", "\"No. I was at work when it went out, and I did not create the album or send any email.\""), .direct("What did you mean by the text about {V}'s parents?", "\"I was angry and said something cruel. I never planned to act on it, and I regretted it immediately.\""), .direct("How did the album end up on your laptop?", "\"Someone was at my place that night. I was not home. I leave the laptop on the common table.\""), .direct("Who knew your passcode?", "\"Everyone in the house. It was a shared household, and we all used the same few devices.\""), .direct("Did you keep the photos?", "\"I should have deleted them. I did not, and that was a mistake. I never shared them with anyone.\""), .direct("What do you want {V} to know?", "\"I am sorry for the pain this caused. I did not do it, and I hope whoever did is held accountable.\""), .cross("The album was built from your laptop on your home connection, wasn't it?", "\"That is what they say. I was not there, and anyone in the house could use it.\""), .cross("You wrote that {V}'s parents deserve to know, didn't you?", "\"Yes, in anger. It was an awful thing to say, and I take responsibility for those words.\""), .cross("The recovery number on the throwaway address is your old line, isn't it?", "\"It is a number I used to have. I do not know who set up that address.\""), .cross("You are the only person who had the photos, aren't you?", "\"I was the only one {V} sent them to. The cloud plan was shared, so others could have reached them.\""), .cross("Can you prove you were at work at 11:20?", "\"My timeclock shows I was at work until late. I did not send anything from a laptop at home.\"")],
        openings: ("Five weeks after {V} ended a relationship with {D}, an anonymous email sent a link to private photos to {V}'s parents and two coworkers. The album was built at 11:20 p.m. from {D}'s laptop, and a text from {D} warned {V}'s parents deserved to know.", "{D} was at work when the link went out. The account was a shared plan, {V}'s old tablet was still signed in, and several people used {D}'s laptop and knew the passcode."),
        closings: ("A laptop at {D}'s home, a throwaway address with {D}'s old number, and a text promising to tell {V}'s parents. Each clue points back to one person.", "A shared plan, a shared laptop, a houseful of people, and a timeclock. The State has motive and an angry text, and has not shown who was at the keyboard."),
        timeline: [(-35, "{V} ends the relationship."), (-5, "{DL} texts {V} about {V.his} parents."), (0, "11:20 p.m.: the album is created and shared."), (1, "{V}'s parent calls {V}."), (30, "Platform records obtained by court order.")],
        identified: "An account in {DL}'s name and a throwaway email.",
        aggravating: ["The images were sent to the victim's family and coworkers"],
        mood: .wantsConviction,
        impact: "My parents opened it before I could stop them.")

    static let clubAmbushKillingV1 = SmallCases.make(
        key: "story.clubAmbushKilling",
        category: .violent,
        headlines: ["Biker Club Member Shot Dead at Gravel Pit Meeting", "Trail Camera Catches a Truck Leaving"],
        law: "murder1",
        threshold: 9,
        spec: "Unlawfully killed {V} with malice, premeditation, and deliberation, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V}, a biker club member, was shot at a gravel pit on {DATE} after a text asked {V.him} to meet alone. A trail camera caught a truck leaving. Casings matched a rifle owned by {D}. {DL} says {D.he} was fishing at a creek nearby.",
        state: [E(.digital, 3, "Trail Camera", "A truck like {D}'s enters at 6:40 p.m. and leaves at 7:05."), E(.digital, 3, "Text", "\"Pit tonight at 7. Come alone.\" Sent from a phone bought with cash."), E(.forensic, 2, "Casings", ".308 casings match a rifle in {D}'s cabinet.", .search), E(.forensic, 2, "Autopsy", "A rifle wound to the chest.")],
        defense: [E(.statement, 1, "Fishing", "{DL} says {D.he} was fishing at a creek.")],
        role: "SBI agent",
        exam: [.direct("What is your role?", "\"I am an SBI agent. I investigate homicides across the state and processed the scene at the gravel pit.\""), .direct("What happened to {V} on {DATE}?", "\"{V} was shot at a gravel pit after a text asked {V.him} to meet alone. The autopsy shows a rifle wound to the chest.\""), .direct("What did the text say?", "\"'Pit tonight at 7. Come alone.' It came from a phone bought with cash, so it was never tied to a name.\""), .direct("What did the trail camera capture?", "\"A truck like {D}'s entering at 6:40 p.m. and leaving at 7:05, which brackets the time of the shooting.\""), .direct("What did you recover at the scene?", "\"Spent .308 casings. Testing matched them to a rifle in {D}'s gun cabinet, which we seized under a search warrant.\""), .direct("What did {DL} tell you?", "\"That {D} was fishing at a creek nearby that evening and had nothing to do with the pit.\""), .cross("Can you read the plate on the truck in the camera?", "\"No. The image shows a truck like {D}'s, not a readable plate. It is the model and color.\""), .cross("Did anyone see {DL} at the pit?", "\"No. We have no eyewitness who places {D} there. The case rests on the camera, casings, and the rifle.\""), .cross("Did you find a second truck of the same make?", "\"Yes. A rival the club had threatened owned one. I looked into it, and I cannot rule it out.\""), .cross("Could someone else have used {DL}'s rifle?", "\"The rifle was in a cabinet. I do not know who had access to the cabinet.\""), .cross("Was the phone that sent the text ever found?", "\"No. It was bought with cash and was never recovered, so nothing connects it to {D}.\"")],
        defenseRole: "Fishing buddy",
        defenseExam: [.direct("How do you know {DL}?", "\"We fish together most weekends. We have known each other for years.\""), .direct("Where were you the evening of {DATE}?", "\"At the creek near the pit with {D}. I stopped by around dusk because I knew {D} would be there.\""), .direct("What time did you arrive?", "\"A little before seven. I remember because the light was fading and I had just finished work.\""), .direct("What was {DL} doing?", "\"Casting a line and sitting on a bucket. {D} had a thermos and was relaxed.\""), .direct("Did you notice anything unusual?", "\"Not at all. We talked about fishing and the weather, and then I went home.\""), .direct("How would you describe {DL}?", "\"Quiet and easygoing. I have never seen {D} lose a temper or pick a fight.\""), .cross("How long were you with {DL}?", "\"Maybe twenty minutes. I did not stay long.\""), .cross("Where is the creek compared to the pit?", "\"A few miles away. It is close enough to drive in about ten minutes.\""), .cross("Were you with {DL} before you arrived?", "\"No. {D} was already there when I came.\""), .cross("Did you hear anything about the shooting that night?", "\"No. I heard about it the next day.\""), .cross("Did {DL} mention the club?", "\"Not that evening.\"")],
        theory: ("{D} lured {V} to a pit and shot {V.him}.", "A man fishing."),
        allocution: "\"I can't take it back.\"",
        truths: ("{DL} bought a new scope the week before.", "A second truck of the same make belonged to a rival the club had threatened."),
        defendant: [.direct("Where were you the evening {V} was killed?", "\"At a creek a few miles from the pit, fishing. I went by myself for some peace and quiet after work.\""), .direct("Did you see anyone while you were fishing?", "\"A buddy stopped by around dusk and we talked. My buddy can tell you I was there.\""), .direct("Why does a truck like yours show on the trail camera?", "\"It is a common truck. Half the county drives one like it, and a rival of the club owns one too.\""), .direct("What about the casings from your rifle?", "\"I own a .308, and I hunt with it. Many hunters have one. I did not fire it at {V}.\""), .direct("Why did you buy a new scope the week before?", "\"I planned a hunting trip and wanted a better scope. It was an ordinary purchase for the season.\""), .direct("Did you want {V} dead?", "\"No. We had our differences, but I never wanted anyone killed.\""), .cross("Your rifle's casings were found at the scene, weren't they?", "\"So the agent says. I cannot explain how, and I did not fire it there.\""), .cross("You bought a new scope the week before the shooting, didn't you?", "\"Yes. I bought it for deer season, and the timing is a coincidence.\""), .cross("You had a run-in with {V}'s club before, didn't you?", "\"We had words. A lot of people did, and it never turned violent for me.\""), .cross("Only your buddy can vouch for you at the creek, correct?", "\"Yes, a friend. I did not take a photo or keep a receipt.\""), .cross("Your truck leaves the pit at 7:05, doesn't it?", "\"A truck like mine does. I do not know whose it was.\"")],
        openings: ("{V} was lured to a gravel pit by a text that said come alone and was shot in the chest. A truck like {D}'s was on the trail camera, and the casings match a rifle in {D}'s cabinet. The State will show the camera, the casings, and the text.", "A common truck, a common rifle, and a rival of the club who owns the same make. {D} says {D.he} was fishing, and a fishing buddy will tell you where {D} was."),
        closings: ("A text that said come alone, a truck like {D}'s entering and leaving the pit, and casings from {D}'s rifle. The evidence points to one person.", "A truck anyone could drive, a rifle many hunters own, and an alibi at a creek. The State has not proved {D} pulled the trigger."),
        timeline: [(-10, "{DL} argues with the club."), (0, "6:40 p.m.: a truck enters the pit."), (0, "7 p.m.: shots."), (0, "9 p.m.: {V} is found.")],
        identified: "A trail camera and casings.",
        aggravating: ["The offense involved a firearm"],
        mood: .wantsConviction,
        impact: "He held our club together.",
        doctrines: ["burdenOfProof"],
        genders: ["V": .male])

    static let constructionDumpingV1 = SmallCases.make(
        key: "story.constructionDumping",
        category: .property,
        headlines: ["Gray Slurry Poured Into Farm Pond, Dead Fish Float", "Concrete Truck Log Points to Local Contractor"],
        law: "injuryRealProperty",
        spec: "Willfully and wantonly injured the real property of {V}, farmland, causing damage of $4,200, on {DATE}.",
        ages: 25...60,
        victim: true,
        summary: "{V} found a farm pond gone chalky gray with dead bass on {DATE}. A mixer truck's GPS log showed a stop at the pond gate after midnight. The truck belongs to {D}'s concrete company. Cleanup and restocking cost $4,200. {DL} says a driver dumped it without permission.",
        state: [E(.digital, 3, "Truck GPS", "Mixer truck 7 stops at the pond gate for 25 minutes after midnight."), E(.forensic, 2, "Water Sample", "Concrete residue and high alkalinity.", .search)],
        defense: [E(.statement, 1, "Driver Dumped It", "{DL} says a driver acted alone.")],
        role: "Landowner",
        exam: [.direct("What did you find on {DATE}?", "\"My farm pond had gone chalky gray, and the bass were floating dead along the bank. It looked like something had poisoned it.\""), .direct("How did you trace it?", "\"A mixer truck's GPS log showed a stop at my pond gate after midnight. Truck 7 sat there for twenty-five minutes.\""), .direct("Whose truck was it?", "\"It belongs to {D}'s concrete company. The company name was on the log.\""), .direct("What did the water sample show?", "\"Concrete residue and very high alkalinity. That is what kills fish when wet concrete washes in.\""), .direct("What did the cleanup cost?", "\"$4,200 for cleanup and restocking the pond with fish.\""), .direct("What did {DL} say?", "\"That a driver dumped it without permission and that the company never told anyone to do it.\""), .direct("What did the dispatcher log show about what {D} said that night?", "\"It shows {D} told the dispatcher to find somewhere to rinse out. The truck's chute was then opened at my pond gate, and I found the pond gray by morning.\""), .cross("Did you see the truck dump at your pond?", "\"No. I found the pond afterward. I only have the GPS log and the water sample.\""), .cross("Can you say who was driving?", "\"The company says a driver it had fired the day before. I cannot confirm that myself.\""), .cross("Did {DL} offer to pay for the damage?", "\"Yes, after I called. The offer came late, but it came.\""), .cross("Could runoff from another source cause that alkalinity?", "\"Unlikely at that level. Concrete is the obvious source, but I am not a chemist.\""), .cross("Did {DL} deny the truck was there?", "\"No. {D} agreed the log was accurate and said a driver did it alone.\"")],
        theory: ("{D}'s company dumped washout into a pond.", "A driver acting alone."),
        allocution: "\"It was our truck. I'll pay.\"",
        truths: ("{DL} told the dispatcher that night to find 'somewhere to rinse out.'", "The truck's chute was opened by a driver {DL} had fired the day before."),
        defendant: [.direct("What is your business?", "\"I own a concrete company. We run mixer trucks to job sites around the county.\""), .direct("Did you tell a driver to dump at that pond?", "\"No. I never told anyone to rinse out into a private pond. That is not how I run my business.\""), .direct("What did you tell the dispatcher?", "\"That the driver should find somewhere to rinse out. I meant a wash-out area, not someone's pond.\""), .direct("Looking back, how do you feel about the fish?", "\"Awful. I would have paid for the damage if I had known what happened.\""), .direct("Will you pay for it now?", "\"Yes, I will make it right. That is what I should have done at the start.\""), .direct("Who was the driver of Truck 7, and what happened to that driver?", "\"A driver I had fired the day before. The driver still had the truck keys that night, and I did not tell anyone to dump at the pond.\""), .cross("The GPS shows your truck at the gate for twenty-five minutes, doesn't it?", "\"Yes. It does, and I did not know until later.\""), .cross("You told the dispatcher to find somewhere to rinse out, didn't you?", "\"I did. I did not mean a private pond.\""), .cross("The driver you fired still had your truck, correct?", "\"Yes. I should have taken the keys back right away.\""), .cross("Your company profits when drivers dump quickly, don't they?", "\"Dumping quickly saves time, but I never pushed anyone to break the law.\""), .cross("You did not call the landowner afterward, did you?", "\"No. I did not know about it until the complaint.\"")],
        openings: ("A farm pond turned chalky gray and the bass died. A mixer truck's GPS log shows a stop at the pond gate after midnight, and the truck belongs to {D}'s concrete company. The State will show the GPS, the water sample, and what {D} told the dispatcher.", "A driver fired the day before and a truck that never came back. {D} says the dumping was the driver's act, not the company's."),
        closings: ("Truck 7 at the pond gate for twenty-five minutes after midnight, a dispatcher told to find somewhere to rinse out, and a pond turned gray with dead bass. The company's truck did it, and the company answers.", "A driver fired the day before and a truck that never came back. {D} says the dumping was the work of one person acting alone, and the State must prove the company ordered it."),
        timeline: [(-1, "{DL} fires a driver."), (0, "12:15 a.m.: the truck stops at the gate."), (0, "12:40 a.m.: the truck leaves."), (0, "Morning: {V} finds the pond.")],
        identified: "A truck GPS log.",
        mood: .wantsConviction)

    static let payrollClerkTheftV1 = SmallCases.make(
        key: "story.payrollClerkTheft",
        category: .whiteCollar,
        headlines: ["Accounts Payable Clerk Paid Invoices to a Shell Company for Three Years", "New Owner's Audit Finds Vendor That Does Not Exist"],
        law: "embezzlement100k",
        threshold: 8,
        spec: "Embezzled over $100,000 entrusted to {D} by {V}, an employer, on {DATE}.",
        ages: 30...62,
        victim: true,
        summary: "A new owner's audit on {DATE} found $134,000 in invoices paid over three years to a vendor with no employees, no trucks, and a mailbox address. The approvals carried {D}'s login. {DL} says the vendor list was approved by the former owner.",
        state: [E(.document, 3, "Audit", "$134,000 paid to one vendor that never delivered anything."), E(.digital, 3, "Approval Records", "Each payment approved under {D}'s credentials."), E(.document, 2, "Vendor Filing", "The vendor registered at a mailbox shared with {D}'s relative.")],
        defense: [E(.statement, 1, "Owner Approved", "{DL} says the former owner approved the vendor.")],
        role: "Company owner",
        exam: [.direct("What did the new audit find?", "\"$134,000 in invoices paid over three years to one vendor that has no employees, no trucks, and only a mailbox address.\""), .direct("Whose login approved the payments?", "\"{D}'s. Each payment was approved under {D}'s credentials, according to the approval records.\""), .direct("What does the vendor filing show?", "\"The vendor registered at a mailbox shared with a relative of {D}. It is a mailbox store, not a business address.\""), .direct("What was {D}'s role?", "\"Payroll clerk, handling payments, approvals, and records. {D} worked at the company for several years.\""), .direct("Did the vendor ever deliver anything?", "\"Not a single item. We found no deliveries, no work orders, and no one at the company who ever met the vendor.\""), .direct("How did you find this?", "\"I bought the company and ran an audit after I took over. The invoices stood out because the vendor was unfamiliar.\""), .cross("Could the former owner approve vendors?", "\"Yes. The former owner could add vendors and approve invoices, and I understand did so at times.\""), .cross("Who approved the first invoice?", "\"The former owner, I believe. The first approvals came before {D} took on most of the payment work.\""), .cross("Who could add vendors to the system?", "\"The owner and anyone with admin rights. Several people had those rights, including {D}.\""), .cross("Did you find {D} receiving any of the money?", "\"No. We traced payments to the vendor's account, and I cannot say yet where it went after that.\""), .cross("Did {D} cooperate with the audit?", "\"Yes. {D} answered questions and did not object to the review.\"")],
        defenseRole: "Outside bookkeeper",
        defenseExam: [.direct("What do you do for the company?", "\"I am an outside bookkeeper. I review the books each quarter and reconcile accounts.\""), .direct("Who could add vendors to the payment system?", "\"The owner and anyone with admin rights. The settings were never tightly controlled.\""), .direct("Did {D} have admin rights?", "\"Yes. Most office staff had some level of admin rights, because the system was set up that way.\""), .direct("Did you notice the vendor in your reviews?", "\"I saw the name, but it was on the list the former owner approved, so I did not question it.\""), .direct("How were invoices normally approved?", "\"By anyone with approval rights, using a login. The logins were shared or written down in places.\""), .direct("Where did people keep their passwords?", "\"On sticky notes and in drawers. I mentioned it to the owner more than once, and it did not change.\""), .cross("Did you ever check whether the vendor delivered anything?", "\"No. That was not part of my review. I checked that invoices matched payments.\""), .cross("Did you see the approval records showing {D}'s login?", "\"After the audit, yes. They show {D}'s login on each payment.\""), .cross("Can a login show who actually clicked?", "\"No. It shows a credential, and sticky notes mean others could use it.\""), .cross("Did you review the vendor's mailbox address?", "\"No. I did not look at the filing, and I did not know a relative of {D} was connected.\""), .cross("Did {D} ever raise the vendor with you?", "\"Not that I recall. {D} processed payments as they came, and I did not hear any special mention.\"")],
        theory: ("{D} paid a fake vendor for years.", "A vendor the old owner approved."),
        allocution: "\"I took it. I'm sorry.\"",
        truths: ("The shell vendor's bank account lists {DL}'s home as its mailing address.", "The former owner's own login approved the first six invoices."),
        defendant: [.direct("Did you create the vendor?", "\"No. I did not set up that vendor, and I did not know it did not exist until the audit.\""), .direct("Did you approve payments?", "\"I processed what I was told. Invoices came in on an approved list, and I entered them.\""), .direct("What about your login?", "\"It was on a sticky note by the printer. Anyone in the office could have used it, and I mentioned that to the owner.\""), .direct("What about your relative's mailbox?", "\"A coincidence. My relative rents a box at that store, and I did not know the vendor used the same one.\""), .direct("Did you ever receive any money from the vendor?", "\"Never. I did not receive one dollar from the vendor, and my bank records will show that.\""), .direct("What do you want the court to know?", "\"I did my job and followed the list. I am sorry about the money, but I did not steal it.\""), .cross("Each payment was approved under your login, wasn't it?", "\"Yes, according to the records. I did not approve them all myself.\""), .cross("You never questioned a vendor with no deliveries, did you?", "\"I did not. It was on the approved list, and I did not think I should.\""), .cross("Your relative's mailbox was the vendor's address, wasn't it?", "\"That is what the filing says. I did not know, and I would not have used a relative's box.\""), .cross("You had admin rights, didn't you?", "\"Yes. Most of us in the office did, and the owner knew.\""), .cross("$134,000 over three years and you noticed nothing?", "\"I noticed vendors, not totals. Payments went out each month, and no one told me anything was wrong.\"")],
        openings: ("A new owner's audit found $134,000 in invoices paid over three years to a vendor with no employees, no trucks, and a mailbox address. Every approval carried {D}'s login, and the vendor registered at a mailbox shared with {D}'s relative.", "The vendor was on a list the former owner approved, and {D}'s login sat on a sticky note by the printer. A payroll clerk who processed what came in is not a thief."),
        closings: ("Three years, one fake vendor, a mailbox shared with {D}'s relative, and {D}'s login on every payment. A clerk who handles all that either knew or chose not to look.", "A vendor the former owner approved, a login anyone could use, and no money traced to {D}. The State has a mailbox and a password, not a thief."),
        timeline: [(-1095, "The vendor is added."), (-1000, "The first payment is approved."), (0, "The audit begins."), (7, "The owner reads the report.")],
        identified: "An audit and approval records.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction)

    static let prankNineOneOneV1 = SmallCases.make(
        key: "story.prankNineOneOne",
        category: .publicOrder,
        headlines: ["False Report of Child Drowning at Lake Dock Sends Rescue Crews Out", "Text to 911 Traced to a Tablet"],
        law: "falseReport",
        spec: "Willfully made a false report to law enforcement, on {DATE}.",
        ages: 18...30,
        victim: false,
        summary: "A text to 911 on {DATE} said a child had gone under at a lake dock. Boats and divers searched for two hours. Nobody was missing. The text came from a tablet on {D}'s home Wi-Fi. {DL} says a visitor used it.",
        state: [E(.digital, 3, "Text-to-911 Log", "The text came from a tablet on {D}'s home network."), E(.document, 2, "Rescue Report", "Two boats and divers searched for two hours.")],
        defense: [E(.statement, 1, "Visitor", "{DL} says a visitor used the tablet.")],
        role: "Dispatch supervisor",
        exam: [.direct("What did the text to 911 say?", "\"It said a child had gone under at a lake dock. It was a text, with no voice call, no name, and no callback.\""), .direct("How did dispatch respond?", "\"We sent two boats and divers to the lake dock. They searched for two hours, and no one was missing.\""), .direct("Where did the text come from?", "\"A tablet at {D}'s address. The text-to-911 log shows the device on {D}'s home Wi-Fi network.\""), .direct("Why does a false text like this matter?", "\"It pulls rescuers away from real emergencies. Two boats and divers for two hours is a real cost and a real risk.\""), .direct("How did you trace it to the tablet?", "\"The carrier gave us the network address and device identifier. Both pointed to the tablet at {D}'s home.\""), .direct("What did you do after the search ended?", "\"We contacted {D}'s address and spoke with {D}. {D} said {D.he} had not sent it.\""), .cross("Could someone else have used that tablet?", "\"If they were in the house, yes. A tablet on a home network can be used by any person in the home.\""), .cross("Was a voice involved in any way?", "\"No. Only text. There is no voice we can identify and no recording.\""), .cross("Does the log tell you who typed?", "\"No. It shows the device and the network. It does not show the person holding the device.\""), .cross("Did {D} live near the lake?", "\"Yes, close to it. That fits {D}'s account of living nearby, and it also fits many other homes.\""), .cross("Did you charge anyone else?", "\"Not so far. We investigated only {D}'s address, which is where the trail ended.\"")],
        theory: ("{D} sent a false drowning report.", "A visitor with a tablet."),
        allocution: "\"I thought it was funny. It was not.\"",
        truths: ("A neighbor's doorbell camera shows {DL} outside holding a tablet that afternoon.", "A visiting cousin admitted typing the text on {DL}'s tablet."),
        defendant: [.direct("Did you send the text?", "\"No. I did not send any text to 911, and I did not know about it until a deputy came to my door.\""), .direct("Who was home that day?", "\"My cousin, who was visiting. We were in the house most of the afternoon, and my cousin used the tablet at times.\""), .direct("Where is your tablet kept?", "\"It sits on the kitchen counter. Anyone in the house can pick it up, and there is no passcode.\""), .direct("Do you live near the lake?", "\"Yes. We live near it, and we see the dock from the road. That does not mean I called about it.\""), .direct("How did you feel when deputies came?", "\"Shocked. I could not believe anyone would send a false call, and I told them I would help find out who did.\""), .direct("What do you want the court to know?", "\"I did not send that text. I am sorry for the rescuers' trouble, and I would never do something like that.\""), .cross("The text came from your tablet on your Wi-Fi, didn't it?", "\"So they say. The tablet is always on the counter, and I was not holding it.\""), .cross("You were home all afternoon, weren't you?", "\"Yes, with my cousin. I did not leave, and I did not send anything.\""), .cross("Who else besides your cousin could have used the tablet?", "\"No one else was there. That is why I say it was my cousin, not me.\""), .cross("Will your cousin say so under oath?", "\"I hope so. I asked, and I want my cousin to tell the truth.\""), .cross("You do not know what your cousin did with the tablet, do you?", "\"I was in another room. I did not watch the tablet, and I do not know what was typed.\"")],
        openings: ("A text to 911 said a child had gone under at a lake dock, and two boats and divers searched for two hours. Nobody was missing, and the text came from a tablet on {D}'s home Wi-Fi.", "{D} did not send that text. A visitor was in the house, the tablet sits on the counter with no passcode, and an address on a network is not the same as a person at a keyboard."),
        closings: ("Two boats, divers, two hours, and a text from {D}'s tablet on {D}'s Wi-Fi. A false rescue call cost real resources, and the trail ends at {D}'s door.", "A tablet on a counter, a cousin in the house, and a log that shows a device and not a person. The State cannot show who typed that text."),
        timeline: [(0, "2:10 p.m.: the text is sent."), (0, "2:30 p.m.: boats launch."), (0, "4:30 p.m.: the search ends.")],
        identified: "A text-to-911 trace.",
        mood: .wantsConviction,
        impact: "Our divers searched cold water for two hours.")

    static let revokedFamilyCrashV1 = SmallCases.make(
        key: "story.revokedFamilyCrash",
        category: .traffic,
        headlines: ["Revoked Driver Rear-Ends Minivan Full of Children at Red Light", "Open Cooler Found Behind Seat"],
        law: "dwlrImpaired",
        threshold: 7,
        spec: "Operated a motor vehicle while license revoked for an impaired driving offense, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "On {DATE}, {D}, whose license was revoked for DWI, rear-ended a minivan stopped at a red light, hurting a parent and two children. {D} blew .10. {DL} says the brakes failed.",
        state: [E(.forensic, 3, "Breath Result", "A result of .10."), E(.document, 3, "DMV Record", "License revoked for impaired driving."), E(.video, 2, "Minivan Dashcam", "The car approaches without braking.")],
        defense: [E(.statement, 1, "Brakes", "{DL} says the brakes failed.")],
        role: "Highway Patrol trooper",
        exam: [.direct("What happened that day?", "\"A rear-end collision at a red light. {D}'s car hit a minivan that was stopped, injuring a parent and two children inside.\""), .direct("What did {D}'s breath test show?", "\"A result of .10, above the legal limit of .08, taken at the scene soon after the crash.\""), .direct("What did the DMV record show?", "\"{D}'s license was revoked for impaired driving. {D} should not have been behind the wheel at all.\""), .direct("What did the minivan's dashcam show?", "\"{D}'s car approaching at speed without braking and striking the stopped minivan. The car does not slow before impact.\""), .direct("What did you find on the road?", "\"No skid marks leading to the collision. A driver who brakes hard usually leaves marks, and these were absent.\""), .direct("What was the condition of {D}'s brakes?", "\"Worn. The pads were thin, and the rotors were scored. They were not in good shape.\""), .cross("Did the brakes work at all?", "\"They worked in my testing, at a reduced level. I did not find a total failure.\""), .cross("Is it possible a worn brake fails at a bad moment?", "\"It is possible for a worn brake to give less stopping power. I cannot say it failed on that day.\""), .cross("Did {D} stay at the scene?", "\"Yes. {D} stayed, spoke with us, and cooperated with the breath test.\""), .cross("How badly were the minivan's occupants hurt?", "\"The parent and the children were treated and released. They had pain and bruising but no lasting injury that I know.\""), .cross("Did {D} say anything about the brakes?", "\"Yes. {D} told me the pedal went soft and the car did not stop.\"")],
        defenseRole: "Mechanic",
        defenseExam: [.direct("What do you do for a living?", "\"I am a mechanic. I have repaired brakes for many years and I inspect vehicles after crashes.\""), .direct("Did the brakes on {D}'s car work?", "\"They were worn but they worked. I tested them after the crash and they produced stopping force.\""), .direct("Could the brakes fade?", "\"Not completely. A worn brake can fade with heat, but it still gives some stopping.\""), .direct("What would a failing pedal feel like?", "\"Soft, sinking toward the floor. That can happen with worn pads and low fluid, and it would feel alarming to a driver.\""), .direct("Was the fluid level normal?", "\"A little low, but not empty. I do not think fluid alone explains a total loss.\""), .direct("Would you expect skid marks from a brake failure?", "\"Not necessarily. With weak brakes there may be little to no skid, because the wheels never lock.\""), .cross("Could the brakes have stopped the car if applied early enough?", "\"Likely yes, if the driver braked early enough. A worn brake needs more distance, not less.\""), .cross("Did you see the dashcam video?", "\"I did. It shows no brake lights on the approaching car until after impact, and I cannot explain that.\""), .cross("Would an impaired driver be slower to brake?", "\"Yes. Impairment slows reaction time. That could explain a late stop as well as a brake problem.\""), .cross("Did you inspect the brake booster?", "\"Briefly. I did not find a clear fault, though I did not take it apart.\""), .cross("Do you know whether {D} had been drinking?", "\"I only know the test result I was shown. That was .10.\"")],
        theory: ("{D} drove revoked and impaired.", "A brake failure."),
        allocution: "\"I should have slowed down. I know that now.\"",
        truths: ("Two empty cans were under the seat, still cold.", "A recall notice for the brake booster sat unopened in {DL}'s mail."),
        defendant: [.direct("Had you been drinking?", "\"Two beers, earlier in the evening. I did not think I was over the limit, and I should not have been driving.\""), .direct("What happened as you approached the light?", "\"The brake pedal went soft. I pushed it and it sank, and the car did not slow the way it should.\""), .direct("Why did you drive with a revoked license?", "\"I needed to get to work and I had no ride. It was a bad decision, and I knew I was not supposed to.\""), .direct("Why are there no skid marks?", "\"The pedal went soft, so the wheels never locked. I was pressing as hard as I could and nothing happened.\""), .direct("What did you do after the crash?", "\"I got out and checked on the family. I stayed, called for help, and apologized to everyone.\""), .direct("How are you coping with what happened?", "\"Terrible. Children were hurt, and I will carry that. I never wanted to hurt anyone.\""), .cross("Your license was revoked for impaired driving, wasn't it?", "\"Yes. I knew it. I should not have driven, and I will not make excuses for that.\""), .cross("You blew a .10 after the crash, didn't you?", "\"Yes. That is over the limit, and I accept that. I still say the brake pedal went soft.\""), .cross("The mechanic found your brakes worked, didn't the mechanic?", "\"The mechanic found them worn and they worked at reduced strength. They felt like nothing in the moment.\""), .cross("The dashcam shows no braking before impact, doesn't it?", "\"It shows no brake lights, and I believe I was pressing the pedal. I do not know why the lights did not come on.\""), .cross("You chose to drive after drinking, didn't you?", "\"Yes. That was my decision, and I regret it a lot. I am sorry for what happened.\"")],
        openings: ("{D}, whose license was revoked for impaired driving, rear-ended a minivan stopped at a red light, hurting a parent and two children. {D} blew a .10, and the minivan's dashcam shows the car approaching without braking.", "{D}'s brakes were worn, the pedal went soft, and the car would not stop. A bad decision to drive does not erase a mechanical problem, and the State must prove what caused the crash."),
        closings: ("A revoked license, a .10 breath test, no skid marks, and no brake lights on the dashcam. {D} chose to drive and hit a family stopped at a red light.", "Worn brakes, a pedal that sank, and a driver who knew better than to drive. The State has the drinking and the revocation, and it must still prove the crash was reckless."),
        timeline: [(0, "5 p.m.: a cookout ends."), (0, "5:40 p.m.: the minivan stops at the light."), (0, "5:41 p.m.: the collision."), (0, "6:30 p.m.: the breath test.")],
        identified: "A breath test and the DMV record.",
        aggravating: ["The defendant was impaired at the time of the offense"],
        mood: .wantsConviction,
        impact: "Our kids still cry in the car.",
        doctrines: ["mistakeOfFact"])

    static let painClinicV1 = SmallCases.make(
        key: "story.painClinic",
        category: .drugs,
        headlines: ["Pop-Up Clinic Behind Tire Shop Wrote Oxycodone for Cash", "Pharmacists Flag Same Prescriber Eleven Times"],
        law: "deliverSchedII",
        threshold: 4,
        spec: "Delivered oxycodone by writing prescriptions without a legitimate medical purpose, on {DATE}.",
        ages: 38...60,
        victim: false,
        summary: "{D}, a nurse practitioner, saw patients in a back room of a tire shop for cash. Eleven pharmacies flagged the same prescriber on {DATE}. An undercover officer left with a 60-pill prescription after a five-minute talk and no exam. {DL} says {D.he} treated working people other offices turned away.",
        state: [E(.video, 3, "Undercover Visit", "Five minutes, no exam, $250 cash, a 60-tablet oxycodone prescription."), E(.document, 3, "Pharmacy Flags", "Eleven pharmacies flagged identical quantities from one prescriber."), E(.document, 2, "Cash Ledger", "Daily cash entries from the tire shop room.", .search)],
        defense: [E(.document, 2, "Patient Charts", "Charts with MRI reports for most patients."), E(.document, 1, "Drug Screens", "Screens run on return visits.")],
        role: "Pharmacist",
        exam: [.direct("Why did your pharmacy flag these prescriptions?", "\"Same quantity, same dose, every one. Eleven pharmacies in the area flagged identical 60-tablet oxycodone prescriptions from one prescriber.\""), .direct("Where was the prescriber's clinic?", "\"The back room of a tire shop. Patients waited among stacked tires and paid cash at the door.\""), .direct("What did you notice about the patients?", "\"Many came in groups and picked up the same strength. Several had no other prescriber on record and paid cash.\""), .direct("What did the undercover video show?", "\"A five minute visit, no exam, $250 cash, and a 60-tablet oxycodone prescription handed over at the end.\""), .direct("What does the cash ledger show?", "\"Daily cash entries from the tire shop room, with the amount of each visit. The totals were large for a small space.\""), .direct("Did you fill any of these prescriptions?", "\"Some, after calling the office. I filled the ones where the chart looked complete and the answer was reasonable.\""), .cross("Were the charts valid?", "\"Some had imaging. A few included scans that showed real injuries, and I will not call every chart a fake.\""), .cross("Is it illegal to see patients in a tire shop?", "\"No. Location alone does not break the law. It was the pattern of quantities that made me suspicious.\""), .cross("Do some legitimate pain patients need 60 tablets?", "\"Some might. Patients with serious injuries can be prescribed that amount, so I did not treat it as proof by itself.\""), .cross("Did you speak with {D}?", "\"Yes, on the phone, a few times. {D} answered questions politely and explained the patients' conditions.\""), .cross("Did {D} ever refuse to confirm a prescription?", "\"No. {D} always called back or sent the chart when I asked.\"")],
        defenseRole: "Longtime patient",
        defenseExam: [.direct("Why did you see {D}?", "\"I hurt my back at a sawmill. No other office would take me because I had no insurance and no extra money.\""), .direct("What was the visit like?", "\"Quick. {D} knew my history, looked at my old imaging, asked about the pain, and wrote the prescription.\""), .direct("How did you pay?", "\"Cash, at the door. It was cheaper than the other offices, and I did not have a card.\""), .direct("How long have you been a patient?", "\"About two years. {D} has treated my back through the whole time, adjusting what I need as I heal.\""), .direct("Did you see others at the tire shop clinic?", "\"Yes. Mostly working people, with bad backs and bad knees, who could not get seen anywhere else.\""), .direct("Did {D} ever pressure you to take more medication?", "\"No. {D} asked if I needed it and let me say no when I felt better. I never felt pushed.\""), .cross("Did {D} examine you every visit?", "\"Not every time. Later visits were short, and {D} relied on what I told {D.him} and my earlier exams.\""), .cross("Do you know what other patients got?", "\"No. I do not know their prescriptions. I know only mine.\""), .cross("Did you ever sell any of your pills?", "\"Never. I took them as prescribed, and I am telling you under oath.\""), .cross("Were you told the clinic was in a tire shop?", "\"Yes, and I did not mind. It was clean enough, and {D} was kind.\""), .cross("Did you have an old injury on record?", "\"Yes. It was documented before I ever saw {D}, at a hospital that treated me after the sawmill.\"")],
        theory: ("{D} sold oxycodone prescriptions for cash.", "Care for injured workers."),
        allocution: "\"I trusted my patients too much.\"",
        truths: ("The tire shop owner was paid $200 per clinic day to keep the room open and ask nothing.", "A board review found most patients had documented imaging showing real injuries."),
        defendant: [.direct("Why did you see patients in a tire shop?", "\"Rent. My patients cannot afford clinic fees, and the tire shop gave me a room I could afford.\""), .direct("Who are your patients?", "\"Working people, many without insurance. Sawmill workers, roofers, and drivers who were turned away by other offices.\""), .direct("Why no exam for the undercover officer?", "\"The officer described an old injury and I trusted it. In hindsight I should have examined more carefully.\""), .direct("Why cash only?", "\"Insurance would not pay for what I do, and I could not run a billing office. Cash kept the clinic running.\""), .direct("Why did the same quantity appear on many prescriptions?", "\"I wrote what the charts said. Many had the same type of injury, and I followed the same protocol.\""), .direct("What do you want the jury to understand?", "\"I treated people who had nowhere else to go. If I made mistakes, they came from trying to help.\""), .cross("The officer got a 60-tablet prescription after five minutes, didn't they?", "\"Yes. I trusted what I was told, and I understand how that looks.\""), .cross("Eleven pharmacies flagged identical quantities, didn't they?", "\"Yes. I wrote similar prescriptions for similar injuries, and I did not think about how it would look.\""), .cross("You took cash in a back room of a tire shop, didn't you?", "\"Yes, because my patients could not pay anywhere else. I kept a ledger of every visit.\""), .cross("You did not examine the officer, did you?", "\"No. I did not. That was a failure on my part, and I own it.\""), .cross("How many visits did you see in a day?", "\"A busy day, thirty or more. It was a lot, but I kept notes on each patient.\"")],
        openings: ("{D}, a nurse practitioner, saw patients in a back room of a tire shop for cash, and eleven pharmacies flagged identical 60-tablet oxycodone prescriptions. An undercover officer left after five minutes and no exam with the same prescription.", "{D} treated working people other offices turned away, in a room they could afford, with imaging in many charts. A cheap clinic and a rushed visit are not drug dealing."),
        closings: ("Five minutes, no exam, $250 cash, and a 60-tablet oxycodone prescription, repeated across eleven pharmacies. A back room in a tire shop was no clinic.", "Real patients, real injuries, and a prescriber who tried to help people with nowhere else to go. The State must prove {D} wrote prescriptions with no medical purpose, and it has not."),
        timeline: [(-300, "The back room opens."), (-60, "Pharmacies start calling."), (-14, "The undercover visit."), (0, "Search warrant.")],
        identified: "Pharmacy flags and an undercover visit.",
        aggravating: ["The defendant abused a professional license"],
        mood: .divided)

    static let homeInvasionV1 = SmallCases.make(
        key: "story.homeInvasion",
        category: .robbery,
        headlines: ["Couple Bound With Duct Tape After Fake Package Delivery", "Coin Collection Turns Up at Pawn Shop"],
        law: "dangerousRobbery",
