        state: [E(.document, 3, "Pawn Records", "A friend pawned coin sets, then told police {D} helped."), E(.forensic, 3, "Tape Roll", "{D}'s DNA on the core of a tape roll found by the road.", .search), E(.video, 2, "Doorbell Video", "A thin figure carries a box to the door."), E(.digital, 1, "Phone Records", "{D}'s phone was near the home at 8 p.m.")],
