        state: [E(.video, 3, "Parking Lot Video", "A figure in a rain jacket shoves {V} and takes the bag."), E(.forensic, 3, "Cap DNA", "{D}'s DNA on the cap found at the scene.", .search), E(.document, 2, "Cash Deposit", "{D} deposited $2,000 cash two days later.")],
        defense: [E(.document, 1, "Motorcycle Sale", "{DL} says the deposit was from a motorcycle sold that week.")],
        role: "Market manager",
        exam: [.direct("Please tell us about your role at the farmers market.", "\"I serve as treasurer of a farmers market. I collect stall fees, count the cash after closing, and carry the day's money to a car for deposit.\""), .direct("What happened after closing on {DATE}?", "\"I was carrying $7,400 in cash in a bag toward my car when someone in a rain jacket shoved me down and grabbed it.\""), .direct("Did you see the person's face?", "\"No. The hood of the rain jacket hid it. I saw a figure of average build, and the person ran off toward the far end of the lot.\""), .direct("What injuries did you have?", "\"A bruised hip and a scraped palm. I was sore for weeks, and I was shaken by how fast it happened in a parking lot I know well.\""), .direct("What was left behind at the scene?", "\"A ball cap. Deputies collected it, and DNA on the cap matched {D}, a vendor who had been dropped from the market.\""), .direct("What does the parking lot video show?", "\"A figure in a rain jacket shoves me and takes the bag at about 5:40 in the evening. A van also left the lot afterward.\""), .cross("Did {D} sell at the market before?", "\"Yes, until the spring. {D} was dropped from the market, and I was part of that decision, so I understand why {D} may have been angry.\""), .cross("Could the cap have been left there earlier?", "\"It could have been. {D} says the cap was left weeks earlier, and I cannot say when it was dropped.\""), .cross("Did another vendor wear a similar cap?", "\"Yes. A rival vendor wore one like it. I cannot say that the cap was only {D}'s or that only {D} handled it.\""), .cross("Did you see {D} in the lot that evening?", "\"No. I did not see anyone but the figure in the jacket. I cannot say who was in the rain jacket.\""), .cross("Was the van that left the lot {D}'s?", "\"A van matching {D}'s was seen leaving, but that is not proof. Many vans look alike, and no one read the plate.\"")],
        theory: ("{D} shoved a treasurer down and took the cash.", "A cap left behind long before."),
        allocution: "\"I'm sorry about what happened to {V}.\"",
