        state: [E(.digital, 3, "Email Records", "Seven addresses; four created on the office network.", .search), E(.digital, 2, "Recovery Number", "Two addresses use a recovery number ending in {D}'s digits.", .search)],
        defense: [E(.document, 1, "Shared Network", "Forty coworkers use that office network.")],
        role: "Cyber investigator",
        exam: [.direct("What is your role?", "\"I am a cyber investigator.\""), .direct("What did {V} receive?", "\"180 anonymous emails from seven addresses over three months.\""), .direct("Where were four addresses created?", "\"On the office network.\""), .direct("What did two addresses use?", "\"A recovery number ending in {D}'s digits.\""), .direct("What was in the emails?", "\"The word irregardless, as {D} uses in memos.\""), .direct("What did {DL} say?", "\"That many coworkers share the network and the phrase.\""), .direct("What did the account records show about the two addresses that used a recovery phone number?", "\"They used a recovery number ending in {D}'s digits, and {D}'s personal phone was used to receive the recovery codes. The emails also misuse the word irregardless, as {D} does in memos.\""), .direct("What did {V} do when the anonymous emails began arriving at work and at clients' addresses?", "\"{V} reported them to human resources, and the company brought us in. By then, 180 emails had reached {V} and clients over three months, and several clients were upset.\""), .direct("How many people had access to the office network where four addresses were created?", "\"About forty coworkers use that network. That is why I did not rely on the network alone, and I looked at the recovery number and the phrase usage.\""), .cross("Did you see {DL} send an email?", "\"No. I traced the accounts and the network records.\""), .cross("How many people use that office network?", "\"About forty coworkers.\""), .cross("Does the recovery number prove {DL} made the accounts?", "\"No. It shows whose digits were used.\""), .cross("Did a coworker admit anything?", "\"Yes. A coworker admitted using {D}'s old number to frame {D.him}.\""), .cross("Whose phone received the recovery codes?", "\"A personal phone that belongs to {D}. That is a real problem for {D}.\"")],
        theory: ("{D} harassed a rival with anonymous emails.", "An office network and a common phrase."),
        allocution: "\"I was bitter. I regret it.\"",
        truths: ("{DL}'s personal phone was used to receive the recovery codes.", "A coworker admitted setting up accounts using {DL}'s old number to frame {D.him}."),
        defendant: [.direct("Did you send those emails?", "\"No. I did not send a single one, and I would never harass a coworker or a client.\""), .direct("Why does your phone number show up on two accounts?", "\"Someone used my old number when setting them up. It was in my personal files and a coworker had seen it.\""), .direct("Did you want the promotion?", "\"Yes. I was disappointed when it went to {V}, but I congratulated {V.him} and moved on.\""), .direct("What about the word irregardless?", "\"Many coworkers use it. I use it too, but it is not unusual in our office memos.\""), .direct("Who do you think did this?", "\"A coworker later admitted setting up accounts with my old number. I think that person tried to frame me.\""), .direct("Looking back, how do you feel about being accused?", "\"Hurt and angry. I have worked here for years and never done anything like this.\""), .direct("What do you say about the coworker who set up accounts with your old number?", "\"A coworker later admitted setting up accounts using my old number to frame me. I did not send any email, and I did not ask anyone to do it.\""), .cross("You wanted the promotion that {V} received, didn't you?", "\"Yes, I did. That is no secret.\""), .cross("Your digits appear on two of the accounts, don't they?", "\"They do. I did not put them there.\""), .cross("Your personal phone received the recovery codes, didn't it?", "\"So I have heard. I did not see them.\""), .cross("You use the word irregardless in memos, don't you?", "\"Yes. So do others.\""), .cross("Four accounts came from the office network where you work, correct?", "\"Yes. Forty people use it.\"")],
        openings: ("After {V} won a promotion that {D} had wanted, {V} and {V}'s clients got 180 anonymous emails from seven addresses over three months. Four addresses came from the office network, and two used a recovery number ending in {D}'s digits.", "The defense will explain that forty coworkers share that office network and phrase, and that one coworker later admitted setting up accounts using {D}'s old number to frame {D}. A shared network is not a signature."),
        closings: ("Seven addresses, the office network, a recovery number ending in {D}'s digits, and a phrase {D} uses in memos. {D} had wanted the promotion, and the emails began after {V} won it.", "Forty coworkers on one network, a common word, and a coworker who admitted framing {D} with an old number. The State has not proved that {D} sent a single email."),
        timeline: [(-7, "{V} is promoted."), (0, "The first anonymous email."), (60, "{V} reports to HR."), (90, "Police obtain account records.")],
        identified: "Email records and a recovery number.",
        aggravating: ["The messages were sent to the victim's clients"],
        mood: .indifferent,
