    static let lawnMowerNeighborV1 = SmallCases.make(
        key: "story.lawnMowerNeighbor",
        category: .property,
        headlines: ["Neighbor's Pressure Washer Taken From Carport, Found in Truck Bed", "Neighbor Said to Take It Any Time, Defense Says"],
        law: "misdLarceny",
        spec: "Stole a pressure washer valued at $900 belonging to {V}, on {DATE}.",
        ages: 28...68,
        victim: true,
        summary: "A carport camera caught {D} loading {V}'s $900 pressure washer into a truck at 6:10 a.m. on {DATE}. {V} had texted {D} two days earlier not to touch it. {DL} says {V} had once told {D.him} to take it any time.",
        state: [E(.video, 3, "Carport Camera", "{D} loads the pressure washer into a truck."), E(.digital, 2, "Warning Text", "{V}: 'Don't touch my washer.'")],
        defense: [E(.statement, 1, "Open Invitation", "{DL} says {V} had said to take it any time.")],
        role: "Neighbor",
        exam: [.direct("Tell the jury about living next to {D}.", "\"We have been neighbors for several years. We share a driveway, and we have borrowed things from each other, and I thought we got along.\""), .direct("What did your carport camera show on {DATE}?", "\"{D} loading my $900 pressure washer into a truck at 6:10 in the morning. The camera shows the whole thing in the open.\""), .direct("What did you tell {D} before that?", "\"Two days earlier, I texted {D} not to touch my washer. I wrote don't touch my washer, because I had seen {D} looking at it.\""), .direct("When did you notice it was gone?", "\"At about seven that morning. I went to my carport and saw the empty spot, and I checked the camera right away.\""), .direct("What happened after that?", "\"I learned that {D} offered the washer for sale to a coworker the next day. I called the sheriff, and deputies spoke to {D}.\""), .direct("How did this affect you?", "\"I felt betrayed. The washer cost $900, and I used it for work. I did not expect a neighbor to ignore a warning text.\""), .cross("Had you lent the washer to {D} before?", "\"Twice. Both times I said yes and {D} returned it. That is part of why I texted that this time the answer was no.\""), .cross("Did you ever tell {D} to take it any time?", "\"A year ago, I texted take it any time you need it. I do not remember it clearly, but I know I wrote it.\""), .cross("Did {D} hide the washer?", "\"No. {D} loaded it in the open bed of the truck, in plain view of the camera and the street.\""), .cross("Did {D} see your warning text?", "\"I do not know. I sent it two days before. {D} says {D} did not see it, and I cannot say whether that is true.\""), .cross("Did {D} return the washer?", "\"Eventually, after deputies came. I have it back, but I do not know whether it was damaged.\"")],
        theory: ("{D} took a washer after being told no.", "Standing permission from a neighbor."),
        allocution: "\"I thought it was fine. I'll return it.\"",
        truths: ("{DL} offered the pressure washer for sale to a coworker the next day.", "A year-old text from {V} said, 'take it any time you need it.'"),
        defendant: [.direct("Please describe your relationship with {V}.", "\"We have been neighbors for years. We trade tools and favors, and I thought our friendship was good. I did not think this would turn into a case.\""), .direct("Why did you take the washer so early?", "\"I leave for work at about six, and I borrowed the washer on my way out. I did not mean to hide anything.\""), .direct("What did {V} tell you about taking tools?", "\"A year ago, {V} texted me that I could take it any time I needed it. I took that as a standing permission.\""), .direct("Did you see the warning text that said don't touch my washer?", "\"No. I did not see it. I do not check my texts early in the morning, and I would not have taken it if I had.\""), .direct("Why did you ask a coworker about buying it?", "\"I only asked if the coworker needed one. I was not selling it, and I did not know the coworker would take it that way.\""), .direct("What did you do when deputies came?", "\"I told them where the washer was and gave it back. I was embarrassed, and I apologized to {V}.\""), .cross("You loaded the washer at dawn, didn't you?", "\"Yes. I loaded it in the open bed. I did not hide it, and I did not think anyone would mind.\""), .cross("You offered it to a coworker the next day, didn't you?", "\"I asked if the coworker needed one. I did not name a price, and I did not mean to sell it, but I see how it sounds.\""), .cross("The warning text said not to touch it, didn't it?", "\"Yes. That is what it said. I did not see it, and I know it came two days before.\""), .cross("The old text said take it any time, didn't it?", "\"Yes. It is a year old, and I took it to mean I could take it again. I know that was an assumption.\""), .cross("You did not ask before taking it, did you?", "\"No. I did not. I assumed I could take it, and I should have asked, as I did the first two times.\"")],
        openings: ("A carport camera caught {D} loading {V}'s $900 pressure washer into a truck at 6:10 on the morning of {DATE}. Two days earlier, {V} had texted {D} not to touch it, and {D} offered the washer to a coworker the next day.", "The defense will present a neighbor who was once told to take it any time, and who did not see the warning text. A standing invitation from a year ago is not a theft."),
        closings: ("A camera that shows {D} loading the washer, a warning text that said don't touch my washer, and an offer to sell it to a coworker the next day. {D} was told no and took it anyway.", "A year-old text that said take it any time you need it, and a neighbor who took the washer in the open. The State has not proved that {D} meant to steal."),
        timeline: [(-2, "{V} texts the warning."), (0, "6:10 a.m.: {DL} loads the washer."), (0, "7 a.m.: {V} sees it is gone."), (1, "{DL} offers it to a coworker.")],
        identified: "A carport camera.",
        mood: .indifferent,
        impact: "I have locked it up since.")

