        state: [E(.document, 3, "Dinner Tallies", "$142,000 counted over four years."), E(.document, 3, "Bank Records", "$81,000 deposited."), E(.document, 3, "Personal Account", "Cash deposits to {D}'s account after each dinner.", .search)],
